import{_ as n}from"./chunks/rules-trigger-de.BglIPUQ6.js";import{_ as t,o as r,c as s,a3 as a}from"./chunks/framework.BlfGB29P.js";const i="/images/logic-studio/user-guide/rules-walkthrough-de.jpg",m=JSON.parse('{"title":"Rules","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/rules.md","filePath":"projects/logic-studio/user-guide/rules.md","lastUpdated":1795791313000}'),o={name:"projects/logic-studio/user-guide/rules.md"};function u(l,e,d,h,g,c){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h1><h2 id="regel-fur-ein-flurlicht-erstellen" tabindex="-1">Regel für ein Flurlicht erstellen <a class="header-anchor" href="#regel-fur-ein-flurlicht-erstellen" aria-label="Permalink to &quot;Regel für ein Flurlicht erstellen&quot;">​</a></h2><h3 id="_1-projekt-anlegen" tabindex="-1">1. Projekt anlegen <a class="header-anchor" href="#_1-projekt-anlegen" aria-label="Permalink to &quot;1. Projekt anlegen&quot;">​</a></h3><p>Wähle <strong>Neues Projekt → Regeln</strong> und gib einen Namen ein, etwa <strong>Flurlicht bei Bewegung</strong>. Öffne <strong>Assistent</strong>. Der Dialog führt dich durch <strong>Löst aus</strong>, <strong>Bedingungen</strong>, <strong>Aktionen</strong> und <strong>Übersicht</strong>.</p><h3 id="_2-ausloser-festlegen" tabindex="-1">2. Auslöser festlegen <a class="header-anchor" href="#_2-ausloser-festlegen" aria-label="Permalink to &quot;2. Auslöser festlegen&quot;">​</a></h3><p>Wähle <strong>Zustand</strong>. Trage bei <strong>Entität</strong> deinen Bewegungssensor oder ersten Testhelfer ein. Im Bild ist es <code>binary_sensor.bewegung</code>. Trage bei <strong>Nach</strong> <code>on</code> ein. Lass <strong>Von</strong>, Attribut und Mindestdauer leer. Klicke auf <strong>Weiter</strong>.</p><p><a href="/images/logic-studio/user-guide/rules-trigger-de.jpg"><img src="'+n+'" alt="Zustandsauslöser im ersten Schritt des Rules-Assistenten"></a></p><h3 id="_3-bedingungen-uberspringen" tabindex="-1">3. Bedingungen überspringen <a class="header-anchor" href="#_3-bedingungen-uberspringen" aria-label="Permalink to &quot;3. Bedingungen überspringen&quot;">​</a></h3><p>Klicke im Schritt <strong>Bedingungen</strong> auf <strong>Weiter</strong>. Für dieses Beispiel reicht der Zustandswechsel als Auslöser. Eine zusätzliche Bedingung wäre etwa, dass es nach 18 Uhr ist.</p><h3 id="_4-aktion-hinzufugen" tabindex="-1">4. Aktion hinzufügen <a class="header-anchor" href="#_4-aktion-hinzufugen" aria-label="Permalink to &quot;4. Aktion hinzufügen&quot;">​</a></h3><p>Wähle bei <strong>DANN</strong> <strong>+ Hinzufügen</strong>. Lass als Schritttyp <strong>HA-Aktion</strong> stehen. Wähle <code>light.turn_on</code> und als <strong>Ziel-Entität</strong> deine Testleuchte. In der Demo ist es <code>light.flur</code>. Für einen zweiten Umschalter als Ziel verwende <code>input_boolean.turn_on</code>. Lass <strong>SONST</strong> leer und klicke auf <strong>Weiter</strong>.</p><h3 id="_5-ubersicht-und-yaml-prufen" tabindex="-1">5. Übersicht und YAML prüfen <a class="header-anchor" href="#_5-ubersicht-und-yaml-prufen" aria-label="Permalink to &quot;5. Übersicht und YAML prüfen&quot;">​</a></h3><p>Unter <code>triggers</code> steht die gewählte Entität mit <code>to: &quot;on&quot;</code>. Unter <code>actions</code> stehen die Aktion und ihr Ziel. Klicke auf <strong>Übernehmen</strong>. Im Editor kannst du die Regel speichern, mit <strong>Als HA-YAML öffnen</strong> den Entwurf ansehen und dort die Datei exportieren.</p><h3 id="_6-in-home-assistant-ausprobieren" tabindex="-1">6. In Home Assistant ausprobieren <a class="header-anchor" href="#_6-in-home-assistant-ausprobieren" aria-label="Permalink to &quot;6. In Home Assistant ausprobieren&quot;">​</a></h3><p>Übernimm die geprüfte Automation in Home Assistant. Setze den Auslöser zunächst auf <code>off</code> und dann auf <code>on</code>. Kontrolliere, ob das richtige Ziel eingeschaltet wurde. Im <strong>Trace</strong> der Automation siehst du, welcher Auslöser und welche Aktion ausgeführt wurden.</p><p><a href="/images/logic-studio/user-guide/rules-walkthrough-de.jpg"><img src="'+i+'" alt="Rules mit Zustandsauslöser im Abschnitt FALLS und Lichtaktion im Abschnitt DANN"></a></p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="assistent-und-palette" tabindex="-1">Assistent und Palette <a class="header-anchor" href="#assistent-und-palette" aria-label="Permalink to &quot;Assistent und Palette&quot;">​</a></h3><p>Der Assistent führt durch Auslöser, Bedingungen und Aktionen. In der Palette kannst du suchen und Bausteine zum passenden Abschnitt ziehen.</p><h3 id="ausloser" tabindex="-1">Auslöser <a class="header-anchor" href="#ausloser" aria-label="Permalink to &quot;Auslöser&quot;">​</a></h3><p>Ein Auslöser startet die Regel. Wähle Zustand mit Von/Nach, Attribut und Mindestdauer, Zahlenschwelle, Uhrzeit, Helferuhrzeit, Sonne mit Versatz, MQTT, HA-Ereignis oder HA-Start. Bereich und Label fassen ausgewählte Entitäten zusammen.</p><h3 id="bedingungen" tabindex="-1">Bedingungen <a class="header-anchor" href="#bedingungen" aria-label="Permalink to &quot;Bedingungen&quot;">​</a></h3><p>Prüfe Zustand, Zahlenwert, Attribut, Uhrzeit oder Wochentag. UND verlangt alle Prüfungen, ODER mindestens eine, NICHT kehrt die Prüfung um.</p><h3 id="ausgelost-durch" tabindex="-1">Ausgelöst durch <a class="header-anchor" href="#ausgelost-durch" aria-label="Permalink to &quot;Ausgelöst durch&quot;">​</a></h3><p>Gib Auslösern IDs wie <code>first</code> und <code>second</code>. Prüfe die ID unter UND. Damit entscheidet dieselbe Regel je nach Auslöser zwischen DANN und SONST.</p><h3 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h3><p>Im Expertenmodus kannst du eine native HA-Template-Bedingung eingeben. Ihr Ergebnis entscheidet, ob die Bedingung erfüllt ist.</p><h3 id="aktionen-und-zweige" tabindex="-1">Aktionen und Zweige <a class="header-anchor" href="#aktionen-und-zweige" aria-label="Permalink to &quot;Aktionen und Zweige&quot;">​</a></h3><p>Füge mehrere Aktionen in der gewünschten Reihenfolge ein. Wähle Ziel und Parameter oder nutze Verzögerung, Warten auf Zustand, Skriptaufruf oder Benachrichtigung.</p><h3 id="yaml-und-rules-json" tabindex="-1">YAML und Rules-JSON <a class="header-anchor" href="#yaml-und-rules-json" aria-label="Permalink to &quot;YAML und Rules-JSON&quot;">​</a></h3><p>YAML ist für Home Assistant. Rules-JSON als Text oder Datei kannst du wieder im Rules-Editor öffnen.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn ein Schwellenwert-Auslöser nur einmal feuert, bringe den Wert erst wieder aus dem Schwellenbereich und anschließend erneut hinein.</p>',33)])])}const b=t(o,[["render",u]]);export{m as __pageData,b as default};
